(()=>{'use strict';const dialog=document.querySelector('dialog');let opener;document.querySelectorAll('.zoom').forEach(button=>button.addEventListener('click',()=>{opener=button;const img=button.querySelector('img');dialog.querySelector('img').src=img.src;dialog.querySelector('img').alt=img.alt;dialog.querySelector('p').textContent=img.alt;dialog.showModal()}));dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{const lang=button.dataset.language;document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.getElementById('design-ar').hidden=lang!=='ar';document.getElementById('design-en').hidden=lang!=='en'}))})();
